import { LitElement, html, customElement, css } from "@umbraco-cms/backoffice/external/lit";
import { UmbElementMixin } from "@umbraco-cms/backoffice/element-api";
import { startBreathingAnimation } from '../scripts/breathing-animation';

@customElement('breath-square-element')

export default class BreathSquareElement extends UmbElementMixin(LitElement) {

  connectedCallback() {
    super.connectedCallback();
    setTimeout(() => startBreathingAnimation(this.shadowRoot!), 2000);
  }

  render() {
    return html`
    <div class="container">
      <div class="countdown"></div>
      <div class="breath-box">
        <div class="box-countdown">4</div>
        <div class="ball"></div>
      </div>
      <div class="breath-text"></div>
    </div>
        `;
  }

  static styles = [
    css`
            .container {
            position: relative;
            width: 300px;
            height: 100px;
            margin-bottom: 20px;
        }

         .breath-box {
            width: 100px;
            height: 100px;
            margin-left: 100px;
            background-color: #f5c1bc;
            border-radius: 10px;
            position: absolute;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 1.5em;
            color: #3544b1;
        }

        .ball {
            width: 20px;
            height: 20px;
            background-color: #3544b1;
            border-radius: 50%;
            position: absolute;
            animation: roll 16s infinite;
            animation-play-state: paused;
        }

        @keyframes roll {
            0% {
                top: 0;
                left: 0;
            }
            25% {
                top: 0;
                left: 80px;
            }
            50% {
                top: 80px;
                left: 80px;
            }
            75% {
                top: 80px;
                left: 0;
            }
            100% {
                top: 0;
                left: 0;
            }
        }

        .breath-text {
            font-size: 1.2em;
            color: #3544b1;
            padding-top: 120px;
            text-align: center;
        }

        .countdown {
            font-size: 2em;
            color: #3544b1;
            margin-bottom: 20px;
        }

    `];
}

declare global {
  interface HTMLElementTagNameMap {
    'breath-square-element': BreathSquareElement;
  }
}
